[n, m] = list(map(int, input().split()))
land = []
for i in range(n):
	land.append(list(map(int, list(input()))))
	land[i].append(0)
updist = []
rectrep = []
for i in range(n):
	rectrep.append([0] * m)
for i in range(n):
	updist.append([0] * (m + 1))
	upstack = [[0, -1]]
	for j in range(m + 1):
		if land[i][j]:
			updist[i][j] = updist[i - 1][j] + 1
		nextht = updist[i][j]
		xcoord = j
		while upstack[-1][1] > nextht:
			pair = upstack.pop()
			if upstack[-1][1] > nextht:
				rectrep[pair[1] - 1][j - pair[0] - 1] += 1
				rectrep[upstack[-1][1] - 1][j - pair[0] - 1] -= 1
			else:
				rectrep[pair[1] - 1][j - pair[0] - 1] += 1
				xcoord = pair[0]
				if nextht > 0:
					rectrep[nextht - 1][j - pair[0] - 1] -= 1
		if nextht > upstack[-1][1]:
			upstack.append([xcoord, nextht])
toprint = []
for i in range(n):
	toprint.append([0] * m)
	toprint[i][m - 1] = rectrep[i][m - 1]
	for j in range(m - 2, -1, -1):
		toprint[i][j] = toprint[i][j + 1] + rectrep[i][j]
	for j in range(m - 2, -1, -1):
		toprint[i][j] = toprint[i][j + 1] + toprint[i][j]
for i in range(n - 2, -1, -1):
	for j in range(m):
		toprint[i][j] = toprint[i + 1][j] + toprint[i][j]
for i in range(n):
	for j in range(m):
		print(toprint[i][j], end=' ')
	print()
